namespace NotificationsApp.Services;

public class NotificationItem
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
}

public class NotificationService
{
    private int _nextId = 4;
    private readonly List<NotificationItem> _notifications = new()
    {
        new() { Id = 1, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-10) },
        new() { Id = 2, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        new() { Id = 3, Message = "New feature available: Dark Mode.", Timestamp = DateTime.UtcNow.AddMinutes(-2) },
    };

    private static readonly string[] SampleMessages =
    [
        "Server maintenance scheduled for tonight.",
        "You have a new follower!",
        "Your export is ready to download.",
        "Reminder: Team meeting in 30 minutes.",
        "Security alert: new login from unknown device.",
        "Your subscription will renew soon.",
    ];

    public Task<List<NotificationItem>> GetNotificationsAsync()
    {
        lock (_notifications)
        {
            return Task.FromResult(_notifications.ToList());
        }
    }

    public Task<List<NotificationItem>> GetNotificationsSinceAsync(int lastId)
    {
        // Simulate new notifications arriving randomly
        lock (_notifications)
        {
            if (Random.Shared.Next(3) == 0) // ~33% chance of a new notification each poll
            {
                var msg = SampleMessages[Random.Shared.Next(SampleMessages.Length)];
                _notifications.Add(new NotificationItem
                {
                    Id = _nextId++,
                    Message = msg,
                    Timestamp = DateTime.UtcNow
                });
            }

            var newer = _notifications.Where(n => n.Id > lastId).ToList();
            return Task.FromResult(newer);
        }
    }
}

